"""Validate GenUP candidate-preference data generated by TripMind."""
from __future__ import annotations
import argparse,json,sys
from collections import Counter,defaultdict
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:sys.path.insert(0,str(ROOT))
from tripmind.processing.genup import parse_target_poi_id
def rows(path):
    with path.open(encoding="utf-8") as f:
        for line in f:
            if line.strip():yield json.loads(line)
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument("--root",default="data/processed/genup_preference");a=p.parse_args();root=Path(a.root);manifest=json.loads((root/"manifest.json").read_text());expected=int(manifest["negatives_per_positive"]);ids=set();counts=Counter();positives=defaultdict(set);records=[]
    for path in sorted(root.glob("*.jsonl")):
        for r in rows(path):
            if r.get("task")!="candidate_poi_preference":raise AssertionError("unexpected task")
            cid=r["context_id"]
            if cid in ids:raise AssertionError(f"duplicate context_id: {cid}")
            ids.add(cid);pos=r["positive_candidate"]["poi_id"]
            if not r["positive_candidate"].get("category"):raise AssertionError("positive candidate lacks category")
            if parse_target_poi_id(r["target_text"])!=pos:raise AssertionError("positive disagrees with target")
            positives[(r["source_dataset"],r["user_key"])].add(pos);records.append(r);counts[r["split"]]+=1
    if not ids:raise AssertionError("no preference contexts found")
    types=Counter()
    for r in records:
        pos=r["positive_candidate"]["poi_id"];hist=set(r.get("history_poi_ids",[]));neg=r["negative_candidates"]
        if len(neg)!=expected:raise AssertionError("wrong negative count")
        nids=[x["poi_id"] for x in neg]
        if len(set(nids))!=len(nids):raise AssertionError("duplicate negative")
        if pos in nids or any(x in hist for x in nids):raise AssertionError("positive/history used as negative")
        key=(r["source_dataset"],r["user_key"])
        if any(x in positives[key] for x in nids):raise AssertionError("known target used as negative")
        for x in neg:
            if not x.get("category"):raise AssertionError("negative lacks category")
            if x.get("negative_type") not in {"same_category","random_unobserved_different_category"}:raise AssertionError("invalid negative type")
            types[x["negative_type"]]+=1
    print("VALIDATED");print("contexts:",len(ids));print("splits:",dict(counts));print("negative_types:",dict(types))
if __name__=="__main__":main()
